ALTER TABLE public.markets ADD COLUMN IF NOT EXISTS supported_locales jsonb NOT NULL DEFAULT '[]'::jsonb CHECK(jsonb_typeof(supported_locales)='array'),ADD COLUMN IF NOT EXISTS country_code text CHECK(country_code IS NULL OR country_code~'^[A-Z]{2}$');
UPDATE public.markets SET supported_locales=CASE code WHEN'TR'THEN'["tr-TR"]'::jsonb WHEN'SA'THEN'["ar-SA","en-SA"]'::jsonb ELSE jsonb_build_array(default_locale)END,country_code=code WHERE supported_locales='[]'::jsonb;
CREATE OR REPLACE FUNCTION public.admin_list_markets(p_actor_id uuid)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$BEGIN IF NOT public.has_permission(p_actor_id,'integrations.manage')THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='FORBIDDEN';END IF;RETURN(SELECT coalesce(jsonb_agg(jsonb_build_object('id',m.id,'code',m.code,'name',m.name,'domain',m.primary_domain,'defaultLocale',m.default_locale,'supportedLocales',m.supported_locales,'currency',m.currency_code,'timezone',m.timezone,'enabled',m.enabled,'checkoutEnabled',coalesce((m.settings->>'checkout_enabled')::boolean,false),'updatedAt',m.updated_at)ORDER BY m.code),'[]'::jsonb)FROM public.markets m);END$$;
CREATE OR REPLACE FUNCTION public.admin_update_market(p_actor_id uuid,p_market_code text,p_name text,p_domain text,p_default_locale text,p_supported_locales jsonb,p_timezone text,p_enabled boolean)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$DECLARE m public.markets%ROWTYPE;BEGIN IF NOT public.has_permission(p_actor_id,'integrations.manage')THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='FORBIDDEN';END IF;IF jsonb_typeof(p_supported_locales)<>'array'OR jsonb_array_length(p_supported_locales)=0 OR NOT p_supported_locales?p_default_locale OR p_domain!~'^[a-z0-9.-]+\.[a-z]{2,}$'THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='INVALID_MARKET_CONFIGURATION';END IF;SELECT*INTO m FROM public.markets WHERE code=upper(p_market_code)FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='MARKET_NOT_FOUND';END IF;IF NOT p_enabled AND coalesce((m.settings->>'checkout_enabled')::boolean,false)THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='DISABLE_CHECKOUT_FIRST';END IF;UPDATE public.markets SET name=trim(p_name),primary_domain=lower(trim(p_domain)),default_locale=p_default_locale,supported_locales=p_supported_locales,timezone=p_timezone,enabled=p_enabled,updated_at=now()WHERE id=m.id;INSERT INTO public.audit_events(market_id,actor_id,actor_type,action,resource_type,resource_id,metadata)VALUES(m.id,p_actor_id,'admin','market.updated','market',m.code,jsonb_build_object('domain',p_domain,'enabled',p_enabled));END$$;
REVOKE ALL ON FUNCTION public.admin_list_markets(uuid),public.admin_update_market(uuid,text,text,text,text,jsonb,text,boolean)FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.admin_list_markets(uuid),public.admin_update_market(uuid,text,text,text,text,jsonb,text,boolean)TO service_role;
